00090                                size_t enhancement_data_size, uint64_t pts, bool is_lcevc_idr) override;
00091 
00092     void push_base_enhancement(const uint8_t *base_data, size_t base_data_size,
00093                                Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS], uint64_t pts,
