00095 
00096     void deserialize_enhancement(const uint8_t *enhancement_data, size_t enhancement_data_size,
00097                                  Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) override;
