00116 int main(int argc, char *argv[]) {
00117     BaseCoding base_video_type;
00118     bool base_external;
00119     bool keep_base;
00120     bool apply_enhancement;
00121     Encapsulation encapsulation;
00122     std::string input_es, output_yuv, base_yuv, input_yuv;
00123     BaseDecoder::Codec file_base;
00124     bool report;
00125     bool dithering_switch;
00126     bool dithering_fixed;
00127     unsigned limit = 1000000;
00128 
00129     try {
00130         cxxopts::Options options_description(argv[0], "LCEVC Decoder " GIT_VERSION);
00131 
00132         // clang-format off
00133         options_description.add_options()
00134             ("i,input_file", "Input elementary stream filename", cxxopts::value<string>()->default_value("input.lvc"))
00135             ("o,output_file", "Output filename for decoded YUV data", cxxopts::value<string>()->default_value("output.yuv"))
00136             ("b,base", "Base codec (avc, hevc, evc, vvc, or yuv)", cxxopts::value<string>()->default_value("avc"))
00137             ("base_encoder", "Base codec (same as --base)", cxxopts::value<string>()->default_value("avc"))
00138             ("base_external", "Use an external base codec executable (select for decoding of monochrome output)", cxxopts::value<bool>()->default_value("false")->implicit_value("true"))
00139             ("y,base_yuv", "Prepared YUV data for base decode", cxxopts::value<string>()->default_value(""))
00140             ("input_yuv", "Original YUV data for PSNR computation", cxxopts::value<string>()->default_value(""))
00141             ("l,limit", "Number of frames to decode", cxxopts::value<unsigned>()->default_value("1000000"))
00142             ("dump_surfaces", "Dump intermediate surfaces to yuv files", cxxopts::value<bool>()->default_value("false")->implicit_value("true"))
00143             ("encapsulation", "Wrap enhancement as SEI or NAL", cxxopts::value<string>()->default_value("nal"))
00144             ("dithering_switch", "Disable decoder dithering independent of configuration in bitstream", cxxopts::value<bool>()->default_value("true"))
00145             ("dithering_fixed", "Use a fixed seed for dithering", cxxopts::value<bool>()->default_value("false")->implicit_value("true"))
00146             ("report", "Calculate PSNR and checksums", cxxopts::value<bool>()->default_value("false")->implicit_value("true"))
00147             ("keep_base", "Keep the base + enhancement bitstreams and base decoded yuv file", cxxopts::value<bool>()->default_value("false")->implicit_value("true"))
00148             ("apply_enhancement", "Apply LCEVC enhancement data (residuals) on output YUV", cxxopts::value<bool>()->default_value("true"))
00149 
00150             // Retain additional arguments for backwards compatibility (to be removed in future release)
00151             ("w,width", "Placeholder (to be removed in future release)", cxxopts::value<unsigned>()->default_value("1920"))
00152             ("h,height", "Placeholder (to be removed in future release)", cxxopts::value<unsigned>()->default_value("1080"))
00153             ("f,format", "Placeholder (to be removed in future release)", cxxopts::value<string>()->default_value("yuv420p"))
00154             ("base_depth", "Placeholder (to be removed in future release)", cxxopts::value<unsigned>()->default_value("0"))
00155 
00156             ("version", "Show version")
00157             ("help", "Show help");
00158         // clang-format on
00159 
00160         const bool show_help = argc == 1;
00161 
00162         // Parse command line
00163         auto options = options_description.parse(argc, argv);
00164 
00165         // Help
00166         if (show_help || options.count("help")) {
00167             cout << options_description.help({""}) << std::endl;
00168             exit(0);
00169         }
00170 
00171         // Version
00172         if (options.count("version")) {
00173             INFO(GIT_VERSION);
00174             exit(0);
00175         }
00176 
00177         // Debugging
00178         Surface::set_dump_surfaces(options["dump_surfaces"].as<bool>());
00179 
00180         // Base codec
00181         //
00182         base_video_type = extract<BaseCoding>(options["base"].as<string>());
00183         if (options["base_encoder"].count())
00184             base_video_type = extract<BaseCoding>(options["base_encoder"].as<string>());
00185 
00186         switch (base_video_type) {
00187         case BaseCoding_AVC:
00188             file_base = BaseDecoder::AVC;
00189             break;
00190         case BaseCoding_HEVC:
00191             file_base = BaseDecoder::HEVC;
00192             break;
00193         case BaseCoding_VVC:
00194             file_base = BaseDecoder::VVC;
00195             break;
00196         case BaseCoding_EVC:
00197             file_base = BaseDecoder::EVC;
00198             break;
00199         case BaseCoding_YUV:
00200             file_base = BaseDecoder::None;
00201             break;
00202         default:
00203             CHECK(0);
00204         }
00205 
00206         base_external = options["base_external"].as<bool>();
00207         keep_base = options["keep_base"].as<bool>();
00208         apply_enhancement = options["apply_enhancement"].as<bool>();
00209 
00210         // Encapsulation
00211         encapsulation = extract<Encapsulation>(options["encapsulation"].as<string>());
00212 
00213         input_es = options["input_file"].as<string>();
00214         output_yuv = options["output_file"].as<string>();
00215         base_yuv = options["base_yuv"].as<string>();
00216         input_yuv = options["input_yuv"].as<string>();
00217 
00218         report = options["report"].as<bool>();
00219         dithering_switch = options["dithering_switch"].as<bool>();
00220         dithering_fixed = options["dithering_fixed"].as<bool>();
00221         limit = options["limit"].as<unsigned>();
00222 
00223         if (base_video_type == BaseCoding_YUV && base_yuv.empty())
00224             ERR("No base codec selected and no base yuv file provided.");
00225 
00226     } catch (const cxxopts::OptionException &e) {
00227         std::cout << "error parsing options: " << e.what() << std::endl;
00228         exit(1);
00229     }
00230 
00231     // Input
00232     //
00233     ESFile es_file;
00234     if (!es_file.Open(input_es, file_base)) {
00235         ERR("Cannot open file: %s\n", input_es.c_str());
00236     }
00237 
00238     // Dummy Output
00239     //
00240     unique_ptr<YUVWriter> yuv_writer(CreateYUVWriter(output_yuv));
00241     // additional Input for PSNR
00242     unique_ptr<YUVReader> yuv_reader(CreateYUVReader(input_yuv, 60));
00243 
00244     // Create Base Video Decpder
00245     DecoderApp app(*yuv_writer, *yuv_reader);
00246     std::unique_ptr<BaseVideoDecoder> base_video_decoder(
00247         CreateBaseVideoDecoder(app, base_video_type, encapsulation, base_external, base_yuv, keep_base));
00248 
00249     app.report_ = report;
00250     app.dithering_switch_ = dithering_switch;
00251     app.dithering_fixed_ = dithering_fixed;
00252     app.apply_enhancement_ = apply_enhancement;
00253 
00254     const float start = (float)(system_timestamp() / 1000000.0);
00255     INFO("-- Starting: %.3f", start);
00256 
00257     base_video_decoder->start();
00258 
00259 #if BITSTREAM_DEBUG
00260     goStat.Reset();
00261     goBits = fopen("BitstreamDec.txt", "w");
00262 #endif
00263 
00264     ESFile::AccessUnit au;
00265 
00266     clock_t EnhaClock0;
00267     EnhaClock0 = clock();
00268     INFO("**** Enh. start %16d", EnhaClock0);
00269 
00270     unsigned count = 0;
00271     while (count < limit) {
00272         ESFile::Result rc = ESFile::EndOfFile;
00273 
00274         try {
00275             rc = es_file.NextAccessUnit(au);
00276         } catch (const runtime_error &e) {
00277             ERR("End of file: %s\n", e.what());
00278             rc = ESFile::NalParsingError;
00279         }
00280 
00281         if (rc != ESFile::Success)
00282             break;
00283 
00284         // Reassemble AU from NALUs
00285         vector<uint8_t> bytes;
00286         for (const auto &n : au.m_nalUnits)
00287             bytes.insert(bytes.end(), n.m_data.begin(), n.m_data.end());
00288 
00289         // Use derived Picture Order Count to construct a plausible PTS
00290         const uint64_t pts = au.m_poc + 1000;
00291         const bool is_base_idr = au.m_pictureType == BaseDecPictType::IDR;
00292 
00293         // Push AU into base decoder
00294         // INFO("AU: size %8d - pts. %8d", bytes.size(), pts);
00295         // REPORT("BASE AU -- pts. %8d size %8d", pts, bytes.size());
00296         base_video_decoder->push_au(bytes.data(), bytes.size(), pts, is_base_idr, au.m_pictureType);
00297 
00298         ++count;
00299     }
00300     INFO("-- Flushing: %.3f", system_timestamp() / 1000000.0);
00301 
00302     base_video_decoder->push_au(0, 0, 0, false, 0);
00303 
00304     clock_t EnhaClock1;
00305     EnhaClock1 = clock();
00306     INFO("**** Enh. stop. %16d", EnhaClock1);
00307     INFO("@@@@ Enh. delta %16d", EnhaClock1 - EnhaClock0);
00308 
00309     INFO("-- Flushed: %.3f", system_timestamp() / 1000000.0);
00310 
00311     const float finish = (float)(system_timestamp() / 1000000.0);
00312     INFO("-- Finished: %.3f", finish);
00313     INFO("-- FPS: %.3f", (float)count / (finish - start));
00314 
00315     base_video_decoder->StatisticsComputation();
00316 
00317 #if BITSTREAM_DEBUG
00318     goStat.Dump();
00319     fflush(goBits);
00320     fclose(goBits);
00321 #endif
00322 }
00323 
00324 DecoderApp::DecoderApp(YUVWriter &writer, YUVReader &reader) : writer_(writer), reader_(reader) {}
00325 
00326 void DecoderApp::push_base_enhancement(const BaseVideoDecoder::BasePicture *base_picture, const uint8_t *enhancement_data,
00327                                        size_t enhancement_data_size, uint64_t pts, bool is_lcevc_idr) {
00328     if (count_ == 0)
00329         INFO("-- Decoding: %.3f", system_timestamp() / 1000000.0);
00330 
00331     // Deserilize LCEVC data
00332     Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS];
00333     decoder_.initialize_decode(Packet::build().contents(enhancement_data, (unsigned)enhancement_data_size).finish(), symbols);
00334     const SignaledConfiguration configuration = decoder_.get_configuration();
00335     decoder_.set_idr(is_lcevc_idr);
00336 
00337     if (count_ == 0) {
00338         // Set-up Output before decoding first frame
00339         unsigned width = configuration.global_configuration.resolution_width;
00340         unsigned height = configuration.global_configuration.resolution_height;
00341         if (configuration.sequence_configuration.conformance_window) {
00342             // Figure out output size after conformance window
00343             Dimensions dimensions = decoder_.get_dimensions();
00344             const unsigned cw = dimensions.crop_unit_width(0), ch = dimensions.crop_unit_height(0);
00345             width -= (configuration.sequence_configuration.conf_win_left_offset * cw +
00346                       configuration.sequence_configuration.conf_win_right_offset * cw);
00347             height -= (configuration.sequence_configuration.conf_win_top_offset * ch +
00348                        configuration.sequence_configuration.conf_win_bottom_offset * ch);
00349         }
00350         const ImageDescription image_description(configuration.global_configuration.image_format, width, height);
00351         writer_.update_data(image_description);
00352         // additional Input for PSNR
00353         if (&reader_)
00354             reader_.update_data(image_description);
00355         if (image_description.colourspace() == Colourspace_Y)
00356             ERR("Please use argument '--base_external=true' for decoding with a monochrome output");
00357     }
00358 
00359     // Base image
00360     //
00361     std::vector<Surface> base_planes;
00362     const ImageDescription base_desc = writer_.image_description()
00363                                            .with_depth(configuration.global_configuration.base_depth)
00364                                            .with_size(base_picture->width_y, base_picture->height_y);
00365     if (configuration.global_configuration.base_depth == 8) {
00366         base_planes.push_back(Surface::build_from<int8_t>()
00367                                   .contents((int8_t *)base_picture->data_y, base_picture->width_y, base_picture->height_y)
00368                                   .finish());
00369         base_planes.push_back(Surface::build_from<int8_t>()
00370                                   .contents((int8_t *)base_picture->data_u, base_picture->width_uv, base_picture->height_uv)
00371                                   .finish());
00372         base_planes.push_back(Surface::build_from<int8_t>()
00373                                   .contents((int8_t *)base_picture->data_v, base_picture->width_uv, base_picture->height_uv)
00374                                   .finish());
00375     } else {
00376         base_planes.push_back(Surface::build_from<int16_t>()
00377                                   .contents((int16_t *)base_picture->data_y, base_picture->width_y, base_picture->height_y)
00378                                   .finish());
00379         base_planes.push_back(Surface::build_from<int16_t>()
00380                                   .contents((int16_t *)base_picture->data_u, base_picture->width_uv, base_picture->height_uv)
00381                                   .finish());
00382         base_planes.push_back(Surface::build_from<int16_t>()
00383                                   .contents((int16_t *)base_picture->data_v, base_picture->width_uv, base_picture->height_uv)
00384                                   .finish());
00385     }
00386 
00387     // INFO("PTS: %" PRIu64 " PSS: %zu", pts, enhancement_data_size);
00388     // REPORT("ENHA AU -- pts. %8d size %8d ", pts, enhancement_data_size);
00389 
00390     if (&reader_) {
00391         auto reference_image = ExpandImage(reader_.read(count_), reader_.description());
00392         auto full_image = decoder_.decode(Image("base", base_desc, pts, base_planes), symbols, reference_image,
00393                                           report_, dithering_switch_, dithering_fixed_, apply_enhancement_);
00394         writer_.write(full_image);
00395     } else {
00396         Image reference_image;
00397         auto full_image = decoder_.decode(Image("base", base_desc, pts, base_planes), symbols, reference_image,
00398                                           report_, dithering_switch_, dithering_fixed_, apply_enhancement_);
00399         writer_.write(full_image);
00400     }
00401 
00402     count_++;
00403 }
00404 
00405 void DecoderApp::push_base_enhancement(const uint8_t *base_data, size_t base_data_size,
00406                                        Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS], uint64_t pts,
00407                                        bool is_lcevc_idr) {
00408 
00409     Dimensions dimensions = decoder_.get_dimensions();
00410     const SignaledConfiguration configuration = decoder_.get_configuration();
00411     decoder_.set_idr(is_lcevc_idr);
00412 
00413     if (count_ == 0) {
00414         INFO("-- Decoding: %.3f", system_timestamp() / 1000000.0);
00415 
00416         // Set-up Output before decoding first frame
00417         unsigned width = configuration.global_configuration.resolution_width;
00418         unsigned height = configuration.global_configuration.resolution_height;
00419         if (configuration.sequence_configuration.conformance_window) {
00420             // Figure out output size after conformance window
00421             const unsigned cw = dimensions.crop_unit_width(0), ch = dimensions.crop_unit_height(0);
00422             width -= (configuration.sequence_configuration.conf_win_left_offset * cw +
00423                       configuration.sequence_configuration.conf_win_right_offset * cw);
00424             height -= (configuration.sequence_configuration.conf_win_top_offset * ch +
00425                        configuration.sequence_configuration.conf_win_bottom_offset * ch);
00426         }
00427         const ImageDescription image_description(configuration.global_configuration.image_format, width, height);
00428         writer_.update_data(image_description);
00429         // additional Input for PSNR
00430         if (&reader_)
00431             reader_.update_data(image_description);
00432     }
00433 
00434     // Base image
00435     //
00436     std::vector<Surface> base_planes;
00437     const ImageDescription base_desc = writer_.image_description()
00438                                            .with_depth(configuration.global_configuration.base_depth)
00439                                            .with_size(dimensions.base_width(), dimensions.base_height());
00440 
00441     if (configuration.global_configuration.base_depth == 8) {
00442         int offset = 0;
00443         for (unsigned plane = 0; plane < base_desc.num_planes(); plane++) {
00444             base_planes.push_back(Surface::build_from<int8_t>()
00445                                       .contents((int8_t *)(base_data + offset), base_desc.width(plane), base_desc.height(plane))
00446                                       .finish());
00447             offset += base_desc.width(plane) * base_desc.height(plane);
00448         }
00449     } else {
00450         int offset = 0;
00451         for (unsigned plane = 0; plane < base_desc.num_planes(); plane++) {
00452             base_planes.push_back(Surface::build_from<int16_t>()
00453                                       .contents((int16_t *)(base_data + offset), base_desc.width(plane), base_desc.height(plane))
00454                                       .finish());
00455             offset += base_desc.width(plane) * base_desc.height(plane) * sizeof(int16_t);
00456         }
00457     }
00458 
00459     // INFO("PTS: %" PRIu64 " PSS: %zu", pts, enhancement_data_size);
00460     // REPORT("ENHA AU -- pts. %8d size %8d ", pts, enhancement_data_size);
00461 
00462     Image base("base", base_desc, pts, base_planes);
00463 
00464     if (&reader_) {
00465         auto reference_image = ExpandImage(reader_.read(count_), reader_.description());
00466         auto full_image = decoder_.decode(base, symbols, reference_image, report_, dithering_switch_, dithering_fixed_,
00467                                           apply_enhancement_);
00468         writer_.write(full_image);
00469     } else {
00470         Image reference_image;
00471         auto full_image = decoder_.decode(base, symbols, reference_image, report_, dithering_switch_, dithering_fixed_,
00472                                           apply_enhancement_);
00473         writer_.write(full_image);
00474     }
00475 
00476     count_++;
00477 }
00478 
00479 // Deserilize LCEVC data
00480 void DecoderApp::deserialize_enhancement(const uint8_t *enhancement_data, size_t enhancement_data_size,
00481                                          Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00482     decoder_.initialize_decode(Packet::build().contents(enhancement_data, (unsigned)enhancement_data_size).finish(), symbols);
00483 }
00484 
00485 Dimensions DecoderApp::get_dimensions() { return decoder_.get_dimensions(); }
00486 
00487 unsigned DecoderApp::get_base_bitdepth() { return decoder_.get_configuration().global_configuration.base_depth; }
00488 
00489 Colourspace DecoderApp::get_colourspace() { return decoder_.get_configuration().global_configuration.colourspace; }
